def parse_amount(text):
    try:
        value = float(text)
    except ValueError:
        return None
    return value if value > 0 else None

def totals(expenses):
    result = {}
    for amount, category in expenses:
        result[category] = round(result.get(category, 0) + amount, 2)
    return result

assert totals([]) == {}
assert totals([(5, "a")]) == {"a": 5}
assert totals([(1.5, "a"), (2, "b"), (0.5, "a")]) == {"a": 2.0, "b": 2}
